from collections import deque
g={"A":["B","C"],"B":["D"],"C":["E"],"D":[],"E":[]}
q=deque(["A"])
seen={"A"}
while q:
    n=q.popleft()
    print(n,end=" ")
    for x in g[n]:
        if x not in seen:
            seen.add(x)
            q.append(x)

